// Generated by vibelang from db/migrations/0014_branch_workspace.ts; the migrate flow writes it again with each batch.
import { Uuid, WebCrypto } from "@smthrs/crypto";
import { Config, Effect } from "effect";
import { SqlClient } from "effect/sql";
import { CONVERSATION_NAMESPACE, HOME_BRANCH } from "../../src/features/branch/contract.js";
import { repoId } from "../../src/features/repo/contract.js";
// The branch workspace's first slice (decision 0013 §1, docs/features/branch-workspace.md#postgres): a branch is the
// workspace, and each branch has one conversation for as long as it lives.
//
// - `branches`: one row per branch the app tracks, with an immutable id; renaming keeps it, and re-creating a ref makes
//   a new one. A branch is tracked by `branch/Track` from GitHub's own refs, so its repository need not be cloned into
//   Code Storage: there is no foreign key to `repositories`.
// - `conversations`: one per branch, whose id is the version 5 UUID of the branch's id (`CONVERSATION_NAMESPACE`), so a
//   device knows it offline.
// - `messages` and `views` name their conversation. An answer stays in its question's conversation: the pair
//   `(question_id, conversation_id)` references the question's own `(id, conversation_id)`.
// - `terminal_sessions`: one terminal per person per branch while it opens or is open (decision 0013 §3). Its bytes are
//   never stored; only its status, and the generation of the machine it runs on.
//
// Every row written before this migration belongs to the conversation of the deployment repository's `main`
// (`GITHUB_REPOSITORY`, default `smithersai/smithers`), keeping its ids and positions, so Will's history stays readable
// at `/app` and on that branch's page.
export default Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    yield* sql `
    CREATE TABLE branches (
      id uuid PRIMARY KEY,
      repo_id text NOT NULL CHECK (char_length(repo_id) BETWEEN 1 AND 300),
      name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 255),
      mode text NOT NULL DEFAULT 'open' CHECK (mode IN ('locked', 'open', 'restricted')),
      base_sha text CHECK (base_sha ~ '^[0-9a-f]{40}([0-9a-f]{24})?$'),
      created_by text,
      created_at timestamptz NOT NULL DEFAULT now(),
      deleted_at timestamptz
    )`;
    // A name names one living branch per repository; a deleted one frees it for a new branch with a new id.
    yield* sql `CREATE UNIQUE INDEX branches_repo_name ON branches (repo_id, name) WHERE deleted_at IS NULL`;
    yield* sql `
    CREATE TABLE conversations (
      id uuid PRIMARY KEY,
      repo_id text NOT NULL,
      branch_id uuid NOT NULL UNIQUE REFERENCES branches (id),
      created_at timestamptz NOT NULL DEFAULT now()
    )`;
    yield* sql `CREATE INDEX conversations_repo ON conversations (repo_id)`;
    yield* sql `
    CREATE TABLE terminal_sessions (
      id uuid PRIMARY KEY,
      branch_id uuid NOT NULL REFERENCES branches (id),
      owner_id text NOT NULL,
      owner_login text NOT NULL,
      generation bigint CHECK (generation >= 1),
      status text NOT NULL CHECK (status IN ('opening', 'open', 'ended', 'failed')),
      ended_reason text CHECK (ended_reason IN ('closed', 'slept', 'lost', 'revoked')),
      failure text CHECK (failure IN ('unavailable', 'checkout')),
      last_screen text CHECK (octet_length(last_screen) <= 65536),
      created_at timestamptz NOT NULL DEFAULT now(),
      updated_at timestamptz NOT NULL DEFAULT now(),
      ended_at timestamptz,
      CHECK ((status = 'ended') = (ended_reason IS NOT NULL)),
      CHECK ((status = 'failed') = (failure IS NOT NULL)),
      CHECK (status <> 'open' OR generation IS NOT NULL)
    )`;
    // One terminal per person per branch while it opens or is open.
    yield* sql `
    CREATE UNIQUE INDEX terminal_sessions_live ON terminal_sessions (branch_id, owner_id)
    WHERE status IN ('opening', 'open')`;
    yield* sql `CREATE INDEX terminal_sessions_branch ON terminal_sessions (branch_id)`;
    // Today's rows move to the deployment repository's `main`.
    const repository = yield* Config.String("GITHUB_REPOSITORY").pipe(Config.withDefault("smithersai/smithers"));
    const [owner = "", name = ""] = repository.split("/");
    const home = repoId(owner, name);
    const [branch] = yield* sql `
    INSERT INTO branches (id, repo_id, name, mode) VALUES (gen_random_uuid(), ${home}, ${HOME_BRANCH}, 'locked')
    RETURNING id`;
    const branchId = branch.id;
    const conversationId = yield* Uuid.v5(CONVERSATION_NAMESPACE, branchId).pipe(Effect.provide(WebCrypto.layer));
    yield* sql `INSERT INTO conversations (id, repo_id, branch_id) VALUES (${conversationId}, ${home}, ${branchId})`;
    yield* sql `ALTER TABLE messages ADD COLUMN conversation_id uuid REFERENCES conversations (id)`;
    yield* sql `UPDATE messages SET conversation_id = ${conversationId}`;
    yield* sql `ALTER TABLE messages ALTER COLUMN conversation_id SET NOT NULL`;
    yield* sql `ALTER TABLE messages ADD CONSTRAINT messages_id_conversation UNIQUE (id, conversation_id)`;
    yield* sql `
    ALTER TABLE messages ADD CONSTRAINT messages_question_conversation
    FOREIGN KEY (question_id, conversation_id) REFERENCES messages (id, conversation_id)`;
    // Each shape and each turn reads one conversation, in order.
    yield* sql `CREATE INDEX messages_conversation_position ON messages (conversation_id, position)`;
    yield* sql `ALTER TABLE views ADD COLUMN conversation_id uuid REFERENCES conversations (id)`;
    yield* sql `UPDATE views SET conversation_id = ${conversationId}`;
    yield* sql `ALTER TABLE views ALTER COLUMN conversation_id SET NOT NULL`;
    yield* sql `CREATE INDEX views_conversation ON views (conversation_id)`;
    // Electric sends whole rows on update and delete, so it needs no superuser to set this itself.
    yield* sql `ALTER TABLE branches REPLICA IDENTITY FULL`;
    yield* sql `ALTER TABLE conversations REPLICA IDENTITY FULL`;
    yield* sql `ALTER TABLE terminal_sessions REPLICA IDENTITY FULL`;
});
